/** Termination kinds (ObjectKind keys) a cable end of the given kind may be cabled to. */
export const CABLE_COMPATIBLE_TERMINATIONS: Readonly<Record<string, readonly string[]>> = {
  circuit_termination: ["circuit_termination", "front_port", "interface", "rear_port"],
  console_port: ["console_server_port", "front_port", "rear_port"],
  console_server_port: ["console_port", "front_port", "rear_port"],
  front_port: ["circuit_termination", "console_port", "console_server_port", "front_port", "interface", "rear_port"],
  interface: ["circuit_termination", "front_port", "interface", "rear_port"],
  power_outlet: ["power_port"],
  power_port: ["power_outlet"],
  rear_port: ["circuit_termination", "console_port", "console_server_port", "front_port", "interface", "rear_port"],
};

export function cableCompatible(a: string, b: string): boolean {
  return (CABLE_COMPATIBLE_TERMINATIONS[a] ?? []).includes(b);
}
